prompt --application/shared_components/security/authorizations/colaborador
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(30607785537919512)
,p_name=>'COLABORADOR'
,p_static_id=>'colaborador'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'declare',
    '  l_qt pls_integer;',
    'begin',
    '  if apex_authorization.is_authorized(''ADMIN_RH'') then',
    '    return true;',
    '  end if;',
    '  select count(*)',
    '    into l_qt',
    '    from colaborador',
    '   where upper(login_apex) = upper(:APP_USER)',
    '     and id_empresa = :G_ID_EMPRESA;',
    '  return l_qt > 0;',
    'end;')))).to_clob
,p_version_scn=>'SH256:1G3A0vriRiDsgUdjFaAyVP7qiwwbgEGr5GEsa8xbkHE'
,p_caching=>'BY_USER_BY_SESSION'
);
end;
