prompt --application/shared_components/logic/application_processes/app_user_cargo
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(20014317405414700)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'APP_USER_CARGO'
,p_static_id=>'app-user-cargo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT G.nome',
'    INTO :APP_USER_CARGO',
'    FROM COLABORADOR C',
'    JOIN CARGO G ON G.id_cargo = C.id_cargo',
'   WHERE UPPER(TRIM(C.login_apex)) = UPPER(TRIM(:APP_USER));',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
unistr('    :APP_USER_CARGO := ''SEM V\00CDNCULO'';'),
'  WHEN TOO_MANY_ROWS THEN',
unistr('    :APP_USER_CARGO := ''M\00DALTIPLOS V\00CDNCULOS'';'),
'  WHEN OTHERS THEN',
'    :APP_USER_CARGO := ''ERRO AO CARREGAR CARGO'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:LBjKa0gXDkthWs89Yy-aK6jwgL0ELxpI9j2EEPe6M-o'
);
end;
/
prompt --application/shared_components/logic/application_processes/app_user_foto
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(20812895050971593)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'APP_USER_FOTO'
,p_static_id=>'app-user-foto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT',
'    CASE',
'      WHEN C.foto_url IS NULL THEN',
'        ''#APP_FILES#default-user.jpeg''',
'      ELSE',
'        ''#APP_FILES#fotos/'' || C.foto_url',
'    END',
'    INTO :APP_USER_FOTO',
'    FROM COLABORADOR C',
'   WHERE UPPER(TRIM(C.login_apex)) = UPPER(TRIM(:APP_USER));',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    :APP_USER_FOTO := ''#APP_FILES#default-user.jpeg'';',
'  WHEN TOO_MANY_ROWS THEN',
'    :APP_USER_FOTO := ''#APP_FILES#default-user.jpeg'';',
'  WHEN OTHERS THEN',
'    :APP_USER_FOTO := ''#APP_FILES#default-user.jpeg'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:7jCFGDSQ6007LDS2eaOjO0ILpUSslxnn2y5MWlicCIk'
);
end;
