prompt --application/shared_components/logic/application_processes/g_nome_empresa
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(14810551092227182)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'G_NOME_EMPRESA'
,p_static_id=>'g-nome-empresa'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT E.nome',
'    INTO :G_NOME_EMPRESA',
'    FROM COLABORADOR C',
'    JOIN EMPRESA E ON E.id_empresa = C.id_empresa',
'   WHERE UPPER(TRIM(C.login_apex)) = UPPER(TRIM(:APP_USER));',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    :G_NOME_EMPRESA := ''SEM VINCULO - usuario: '' || :APP_USER;',
'  WHEN TOO_MANY_ROWS THEN',
'    :G_NOME_EMPRESA := ''MULTIPLOS VINCULOS - usuario: '' || :APP_USER;',
'  WHEN OTHERS THEN',
'    :G_NOME_EMPRESA := ''ERRO: '' || SQLERRM;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:a9ot0x4B-6IQrxJa_qip3HZA8PwgDt7PyqwS1dxNk1g'
);
