'',
'.ch-dept:first-child {',
'    border-top: none;',
'}',
'',
'.ch-contact {',
'    display: flex;',
'    align-items: center;',
'    gap: 10px;',
'    padding: 10px 16px;',
'    text-decoration: none;',
'    color: inherit;',
'    border-left: 3px solid transparent;',
'    transition: background .12s ease;',
'    flex: 0 0 auto;',
'}',
'',
'.ch-contact:hover {',
'    background: var(--ch-surface);',
'}',
'',
'.ch-contact.is-active {',
'    background: var(--ch-blue-soft);',
