'}',
'',
'.ch-avatar-wrap {',
'    position: relative;',
'    flex: 0 0 var(--ch-avatar-size);',
'}',
'',
'.ch-avatar {',
'    width: var(--ch-avatar-size);',
'    height: var(--ch-avatar-size);',
'    border-radius: 50%;',
'    background: var(--ch-avatar-bg);',
'    color: var(--ch-avatar-fg);',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    font-size: 12px;',
'    font-weight: 600;',
'}',
'',
'.ch-dot {',
'    position: absolute;',
'    right: -1px;',
'    bottom: -1px;',
'    width: 10px;',
'    height: 10px;',
'    border-radius: 50%;',
'    border: 2px solid #fff;',
'}',
'',
'.ch-dot--online {',
'    background: var(--ch-online);',
'}',
'',
'.ch-dot--ausente {',
'    background: var(--ch-ausente);',
'}',
'',
'.ch-dot--offline {',
'    background: var(--ch-offline);',
'}',
'',
'.ch-contact-txt {',
'    display: flex;',
'    flex-direction: column;',
'    min-width: 0;',
'}',
'',
'.ch-contact-txt b {',
'    font-size: 13px;',
'    font-weight: 600;',
'    color: var(--ch-text);',
'}',
'',
'.ch-contact-txt small {',
'    font-size: 11px;',
'    color: var(--ch-text-dim);',
'}',
'',
'/* ============================================',
'   Painel de conversa',
'   ============================================ */',
'',
'.ch-chat {',
'    background: #fff;',
'    display: flex;',
'    flex-direction: column;',
'    min-height: 0;',
'    overflow: hidden;',
'}',
'',
unistr('/* repassa a altura pela cadeia de wrappers at\00E9 .ch-msgs */'),
'.ch-chat>div,',
'.ch-chat .col,',
'.ch-chat .col>div,',
'.ch-chat .col>div>div {',
'    display: flex;',
'    flex-direction: column;',
'    flex: 1 1 auto;',
'    min-height: 0;',
'}',
'',
'.ch-msgs {',
'    flex: 1 1 auto;',
'    min-height: 0;',
'    overflow-y: auto;',
'    padding: 24px;',
'    display: flex;',
'    flex-direction: column;',
'    gap: 18px;',
'    background: #fff;',
'}',
'',
'.ch-sep {',
'    text-align: center;',
'    margin: 6px 0;',
'    flex: 0 0 auto;',
'}',
'',
'.ch-sep span {',
'    font-size: 11px;',
'    font-weight: 600;',
