,p_name=>'Lista'
,p_static_id=>'contatos'
,p_parent_plug_id=>wwv_flow_imp.id(23610198081870201)
,p_template=>4502917002193490937
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'[object Object]'
,p_grid_column_css_classes=>'ch-list'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d.nome                          as departamento,',
'       c.id_colaborador,',
'       c.nome_completo,',
'       cg.nome                         as cargo,',
'       c.foto_url,',
'       upper(substr(c.primeiro_nome,1,1) ||',
'             substr(c.ultimo_nome,1,1)) as iniciais,',
'       case',
'         when p.data_ultimo_ping > systimestamp - interval ''5'' minute',
'              and upper(p.status_presenca) = ''ONLINE'' then ''online''',
'         when p.data_ultimo_ping > systimestamp - interval ''30'' minute',
'              then ''ausente''',
'         else ''offline''',
'       end                              as presenca,',
'       case when row_number() over (',
'                   partition by d.nome',
'                   order by c.nome_completo',
'                 ) = 1',
'            then ''<div class="ch-dept">'' || d.nome || ''</div>''',
'       end                              as cab_dept',
'from   colaborador  c',
'join   departamento d  on d.id_departamento = c.id_departamento',
'left   join cargo   cg on cg.id_cargo       = c.id_cargo',
'left   join presenca_colaborador p on p.id_colaborador = c.id_colaborador',
'where  c.status = true',
'and    nvl(upper(c.login_apex),''x'') != upper(:APP_USER)',
'order  by d.nome, c.nome_completo'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(24835283720656544)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1'
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
