,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Colaborador padr\00E3o')
,p_static_id=>unistr('colaborador-padr\00E3o')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'  if :P13_ID_COLABORADOR is null then',
'    select id_colaborador',
'      into :P13_ID_COLABORADOR',
'      from colaborador',
'     where upper(trim(login_apex)) = upper(trim(:APP_USER))',
'       and id_empresa = :G_ID_EMPRESA;',
'  end if;',
'exception',
'  when no_data_found or too_many_rows then',
'    raise_application_error(-20012,',
unistr('      ''Sua conta n\00E3o est\00E1 vinculada a um colaborador desta empresa. Fale com o RH.'');'),
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>29919817957540304
);
